/* ===== NÍVEL AVANÇADO (B2–C1): temas 1 a 7 ===== */
const WEEKS_B2 = [
{ n:1, me:"B", pv:["f","m"], title:"Cuando llegué, ya se habían ido", sub:"Matizes do passado: pluscuamperfecto e contraste",
  tip:`<h3>Pluscuamperfecto: había llegado</h3>
  <p>O <b>pluscuamperfecto</b> (había + participio) marca o que aconteceu <b>antes de outro passado</b>: <i>Cuando llegué, el tren ya <b>había salido</b>.</i> É o nosso "tinha saído".</p>
  <p>Com três tempos você conta qualquer história: <b>imperfecto</b> para o cenário (<i>llovía</i>), <b>indefinido</b> para os fatos (<i>llegué</i>), <b>pluscuamperfecto</b> para o que veio antes (<i>había reservado</i>).</p>
  <p>Marcadores: <b>ya</b>, <b>todavía no</b>, <b>nunca antes</b>, <b>hasta entonces</b>, <b>cuando</b>, <b>en cuanto</b>, <b>nada más</b> + infinitivo (<i>nada más llegar</i> = assim que chegou).</p>
  <p>Repare no <b>pretérito anterior</b> literário (<i>hubo salido</i>): só em livros. Na fala, <i>en cuanto salió</i>.</p>
  <p>Detalhe fino: <b>acababa de</b> + infinitivo = tinha acabado de. <i>Acababa de sentarme cuando sonó el móvil.</i></p>`,
  mission:"Conte uma história em que algo já tinha acontecido quando você chegou. Use três 'había' e um 'acababa de'.",
  dialog:[["A","¿Qué tal en Córdoba? Llegasteis a ver la Mezquita por la mañana, ¿no?","Como foi em Córdoba? Vocês conseguiram ver a Mesquita de manhã, não é?"],["B","Qué va. Cuando llegamos, ya habían cerrado el acceso gratuito. Habíamos leído que era hasta las nueve y media, pero cambió el horario.","Que nada. Quando chegamos, já tinham fechado a entrada gratuita. Tínhamos lido que era até as nove e meia, mas o horário mudou."],["A","Vaya faena. ¿Y qué hicisteis?","Que chato. E o que vocês fizeram?"],["B","Pagamos la entrada normal. Mereció la pena: nunca había visto nada parecido.","Pagamos a entrada normal. Valeu a pena: eu nunca tinha visto nada parecido."],["A","¿Habíais estado antes en una mezquita?","Vocês já tinham estado antes numa mesquita?"],["B","Mi marido sí, en Estambul. Yo no. Acababa de entrar y ya tenía los ojos llenos de lágrimas.","Meu marido sim, em Istambul. Eu não. Tinha acabado de entrar e já estava com os olhos cheios de lágrimas."],["A","Es que ese bosque de columnas te deja sin palabras.","É que aquela floresta de colunas te deixa sem palavras."]],
  meB:"A", dialogB:[["A","Perdone, había reservado una mesa a nombre de Souza para las nueve.","Com licença, eu tinha reservado uma mesa em nome de Souza para as nove."],["B","Déjeme ver… Lo siento, no me consta ninguna reserva con ese nombre.","Deixe eu ver… Sinto muito, não consta nenhuma reserva com esse nome."],["A","La hice ayer por teléfono. Me dijeron que estaba confirmada.","Fiz ontem por telefone. Me disseram que estava confirmada."],["B","Es posible que mi compañero no la haya apuntado. ¿Le importaría esperar diez minutos? Se está quedando libre una mesa.","É possível que meu colega não tenha anotado. Se importaria de esperar dez minutos? Uma mesa está sendo liberada."],["A","No hay problema. Habíamos venido pronto precisamente por eso.","Sem problema. Tínhamos vindo cedo justamente por isso."],["B","Se lo agradezco. Mientras esperan, les invito a una copa de cava.","Agradeço. Enquanto esperam, ofereço uma taça de cava."],["A","Muy amable. Así se arreglan las cosas.","Muito gentil. Assim se resolvem as coisas."]],
  cards:[
   ["Cuando llegamos, ya habían cerrado","Quando chegamos, já tinham fechado"],["Nunca había visto nada parecido","Nunca tinha visto nada parecido"],["Habíamos leído que abría a las nueve","Tínhamos lido que abria às nove"],["¿Habías estado antes en España?","Você já tinha estado antes na Espanha?"],["Acababa de entrar cuando sonó el móvil","Tinha acabado de entrar quando o celular tocou"],
   ["Había reservado una mesa a nombre de Souza","Eu tinha reservado uma mesa em nome de Souza"],["No me consta ninguna reserva","Não consta nenhuma reserva"],["Me dijeron que estaba confirmada","Me disseram que estava confirmada"],["Es posible que no la hayan apuntado","É possível que não tenham anotado","Perfecto de subjuntivo: haya + participio."],["¿Le importaría esperar diez minutos?","Se importaria de esperar dez minutos?"],
   ["Habíamos venido pronto precisamente por eso","Tínhamos vindo cedo justamente por isso"],["Nada más llegar, nos pusimos a buscar hotel","Assim que chegamos, começamos a procurar hotel"],["Hasta entonces nunca había comido cochinillo","Até então nunca tinha comido leitão"],["Ya se habían ido cuando llamé","Já tinham ido quando liguei"],["Todavía no había amanecido","Ainda não tinha amanhecido"],
   ["Vaya faena","Que chato, que azar","Expressão para contratempo."],["Mereció la pena","Valeu a pena"],["Te deja sin palabras","Te deixa sem palavras"],["Cambió el horario sin avisar","Mudou o horário sem avisar"],["Lo habíamos planeado todo","Tínhamos planejado tudo"],
   ["Resultó que el museo estaba cerrado","Acabou que o museu estava fechado","'Resultar que' = acontecer que, acabar que."],["Se nos había olvidado el paraguas","Tínhamos esquecido o guarda-chuva","Se + me/nos: o esquecimento 'acontece' à pessoa."],["Se me había pasado la hora","Tinha perdido a hora"],["Menos mal que habíamos comprado las entradas","Ainda bem que tínhamos comprado os ingressos"],["Así se arreglan las cosas","Assim se resolvem as coisas"],["Al final todo salió redondo","No fim tudo saiu perfeito"]
  ]},
{ n:2, me:"A", pv:["m","f"], title:"Si hubiera sabido…", sub:"Hipóteses e arrependimentos: condicionais",
  tip:`<h3>Os três 'si' do espanhol</h3>
  <p><b>Real</b>: si + presente → presente/futuro. <i>Si llueve, nos quedamos.</i></p>
  <p><b>Improvável ou hipotético</b>: si + <b>imperfecto de subjuntivo</b> → <b>condicional</b>. <i>Si <b>tuviera</b> más tiempo, <b>iría</b> a Cádiz.</i> (se tivesse, iria).</p>
  <p><b>Impossível, passado</b>: si + <b>pluscuamperfecto de subjuntivo</b> → <b>condicional compuesto</b>. <i>Si <b>hubiera sabido</b>, <b>habría venido</b> antes.</i> (se tivesse sabido, teria vindo).</p>
  <p>Imperfecto de subjuntivo: parta da 3ª pessoa plural do indefinido e troque <i>-ron</i> por <i>-ra</i>: <i>tuvieron → tuviera; fueron → fuera; hicieron → hiciera; pudieron → pudiera</i>. A forma <i>-se</i> (tuviese) é igual e um pouco mais formal.</p>
  <p>Arrependimento: <b>Ojalá hubiera…</b> (quem dera eu tivesse…). <b>Tendría que haber…</b> / <b>Debería haber…</b> (deveria ter…). Na fala, muitos dizem <i>si hubiera sabido, hubiera venido</i>: aceito.</p>`,
  mission:"Três arrependimentos leves da viagem com 'Si hubiera…, habría…' e um desejo com 'Ojalá'.",
  dialog:[["A","Si hubiéramos reservado antes, habríamos conseguido entradas para la Alhambra de noche.","Se tivéssemos reservado antes, teríamos conseguido ingressos para a Alhambra à noite."],["B","No te lamentes. Si las hubieras conseguido, habrías dormido tres horas y hoy estarías agotada.","Não se lamente. Se tivesse conseguido, teria dormido três horas e hoje estaria exausta."],["A","Visto así… Pero ojalá tuviéramos un día más.","Visto assim… Mas quem dera tivéssemos um dia a mais."],["B","Si tuvieras un día más, querrías dos. Siempre pasa igual.","Se tivesse um dia a mais, ia querer dois. Sempre acontece igual."],["A","Tienes razón. ¿Qué harías tú si pudieras volver a Granada?","Tem razão. O que você faria se pudesse voltar a Granada?"],["B","Me quedaría una semana en el Albaicín sin hacer nada. Solo mirar.","Ficaria uma semana no Albaicín sem fazer nada. Só olhar."],["A","Pues si volvemos, lo hacemos. Prometido.","Então se voltarmos, fazemos isso. Prometido."]],
  meB:"A", dialogB:[["A","Deberíamos haber cogido el tren en vez del coche. Llevamos dos horas en este atasco.","Deveríamos ter pegado o trem em vez do carro. Estamos há duas horas neste engarrafamento."],["B","Si hubiéramos salido a las siete, como yo decía, ya estaríamos en Valencia.","Se tivéssemos saído às sete, como eu dizia, já estaríamos em Valência."],["A","Ya, ya. Si no te hubieras quedado dormida, habríamos salido a las siete.","Tá, tá. Se você não tivesse ficado dormindo, teríamos saído às sete."],["B","Touché. ¿Y si paramos en el próximo pueblo a comer algo?","Touché. E se parássemos no próximo povoado para comer algo?"],["A","Si encontráramos un sitio con sombra, me parecería un plan perfecto.","Se encontrássemos um lugar com sombra, me pareceria um plano perfeito."],["B","Mira, ahí hay una venta. Si tiene gazpacho, te perdono lo del coche.","Olha, ali tem uma venda. Se tiver gaspacho, te perdoo pelo carro."],["A","Trato hecho.","Negócio fechado."]],
  cards:[
   ["Si hubiéramos reservado antes, habríamos conseguido entradas","Se tivéssemos reservado antes, teríamos conseguido ingressos"],["Si hubiera sabido, habría venido antes","Se tivesse sabido, teria vindo antes"],["Si tuviera más tiempo, iría a Cádiz","Se tivesse mais tempo, iria a Cádiz"],["Si pudiera, me quedaría un mes","Se pudesse, ficaria um mês"],["¿Qué harías tú en mi lugar?","O que você faria no meu lugar?"],
   ["Me quedaría una semana sin hacer nada","Ficaria uma semana sem fazer nada"],["Ojalá tuviéramos un día más","Quem dera tivéssemos um dia a mais"],["Ojalá hubiera venido en primavera","Quem dera eu tivesse vindo na primavera"],["Deberíamos haber cogido el tren","Deveríamos ter pegado o trem"],["Tendría que haber reservado","Eu tinha que ter reservado"],
   ["No te lamentes","Não se lamente"],["Visto así, tienes razón","Visto assim, você tem razão"],["Siempre pasa igual","Sempre acontece igual"],["Llevamos dos horas en este atasco","Estamos há duas horas neste engarrafamento"],["Si no te hubieras quedado dormida…","Se você não tivesse ficado dormindo…"],
   ["¿Y si paramos a comer algo?","E se parássemos para comer algo?","'¿Y si…?' + presente: sugestão."],["Si encontráramos sombra, sería perfecto","Se encontrássemos sombra, seria perfeito"],["Si tiene gazpacho, te perdono","Se tiver gaspacho, te perdoo"],["Trato hecho","Negócio fechado"],["Prometido","Prometido"],
   ["De haberlo sabido, no habría venido","Se eu soubesse, não teria vindo","'De + infinitivo' = condicional elegante."],["En caso de que llueva, avísame","Caso chova, me avise"],["A no ser que cierren, vamos","A menos que fechem, vamos"],["Con tal de que lleguemos, me da igual la hora","Contanto que cheguemos, tanto faz a hora"],["Por si acaso, lleva paraguas","Por precaução, leve guarda-chuva"],["Lo haría otra vez sin dudarlo","Faria de novo sem pensar duas vezes"]
  ]},
{ n:3, me:"B", pv:["m","f"], title:"Me alegra que hayas venido", sub:"Subjuntivo em todos os tempos: emoção, dúvida, concessão",
  tip:`<h3>O subjuntivo como sistema</h3>
  <p>Quatro tempos, uma lógica: <b>presente</b> (venga), <b>perfecto</b> (haya venido), <b>imperfecto</b> (viniera), <b>pluscuamperfecto</b> (hubiera venido). O tempo do subjuntivo acompanha o tempo do verbo principal: <i>Me alegra que <b>vengas</b></i> (hoje) / <i>Me alegró que <b>vinieras</b></i> (ontem).</p>
  <p><b>Emoção</b>: me alegra que, me molesta que, me da pena que, es una lástima que. <b>Dúvida</b>: dudo que, no es seguro que, puede que, quizás (+ subjuntivo quando a dúvida é real). <b>Valoração</b>: es normal que, es raro que, es lógico que, lo mejor es que.</p>
  <p><b>Concessão</b>: <i>aunque <b>sea</b> caro</i> (mesmo que seja) × <i>aunque <b>es</b> caro</i> (embora seja, fato). <i>Por muy caro que sea</i> (por mais caro que seja).</p>
  <p><b>Relativas</b>: <i>Busco un hotel que <b>tenga</b> piscina</i> (não sei se existe) × <i>Conozco un hotel que <b>tiene</b> piscina</i> (existe).</p>`,
  mission:"Reaja a cinco notícias de um amigo (boas e más) com 'me alegra que', 'siento que', 'es una pena que', 'dudo que', 'aunque'.",
  dialog:[["A","¡Ana! Me alegra muchísimo que hayas podido venir. Dudaba que consiguieras el vuelo.","Ana! Fico muito feliz que você tenha conseguido vir. Duvidava que conseguisse o voo."],["B","Casi no lo consigo. Es una lástima que Pedro no haya podido acompañarme.","Quase não consigo. É uma pena que o Pedro não tenha podido me acompanhar."],["A","Es normal que no le dieran vacaciones en febrero. ¿Te molesta que hayamos invitado a mis primos a la cena?","É normal que não tenham dado férias para ele em fevereiro. Te incomoda que tenhamos convidado meus primos para o jantar?"],["B","¡Al contrario! Cuantos más seamos, mejor.","Ao contrário! Quanto mais formos, melhor."],["A","Puede que lleguen un poco tarde. Ya sabes cómo son.","Pode ser que cheguem um pouco atrasados. Você sabe como eles são."],["B","Aunque lleguen a las once, les esperamos con el vino abierto.","Mesmo que cheguem às onze, esperamos com o vinho aberto."],["A","Esa es la actitud. Me encanta que lo veas así.","Essa é a atitude. Adoro que você veja assim."]],
  meB:"B", dialogB:[["A","Buenos días, busco un hotel que esté cerca de la estación y que admita perros.","Bom dia, procuro um hotel que fique perto da estação e que aceite cachorros."],["B","Tenemos uno que cumple las dos condiciones, aunque no es barato.","Temos um que cumpre as duas condições, embora não seja barato."],["A","Por muy caro que sea, lo necesito para una noche. ¿Hay alguno que tenga aparcamiento?","Por mais caro que seja, preciso para uma noite. Tem algum que tenha estacionamento?"],["B","Ese mismo. Es raro que quede alguna habitación, pero déjeme comprobarlo.","Esse mesmo. É raro que sobre algum quarto, mas deixe eu conferir."],["A","Ojalá quede una. Es la única opción que me encaja.","Tomara que sobre um. É a única opção que me serve."],["B","Tiene suerte: queda una doble. ¿Quiere que se la reserve ahora?","Tem sorte: sobra um duplo. Quer que eu reserve agora?"],["A","Sí, por favor, antes de que alguien se me adelante.","Sim, por favor, antes que alguém passe na minha frente."]],
  cards:[
   ["Me alegra que hayas venido","Fico feliz que você tenha vindo"],["Dudaba que consiguieras el vuelo","Duvidava que você conseguisse o voo"],["Es una lástima que no haya podido venir","É uma pena que não tenha podido vir"],["Es normal que no le dieran vacaciones","É normal que não tenham dado férias para ele"],["¿Te molesta que hayamos invitado a mis primos?","Te incomoda que tenhamos convidado meus primos?"],
   ["Cuantos más seamos, mejor","Quanto mais formos, melhor"],["Puede que lleguen tarde","Pode ser que cheguem atrasados"],["Aunque lleguen a las once, les esperamos","Mesmo que cheguem às onze, esperamos"],["Aunque es caro, merece la pena","Embora seja caro, vale a pena","Fato conhecido: indicativo."],["Por muy caro que sea, lo necesito","Por mais caro que seja, preciso"],
   ["Busco un hotel que esté cerca de la estación","Procuro um hotel que fique perto da estação"],["Conozco un hotel que está cerca","Conheço um hotel que fica perto","Existe e você conhece: indicativo."],["¿Hay alguno que tenga aparcamiento?","Tem algum que tenha estacionamento?"],["No hay nadie que hable portugués","Não há ninguém que fale português"],["Es raro que quede alguna habitación","É raro que sobre algum quarto"],
   ["Ojalá quede una","Tomara que sobre um"],["¿Quiere que se la reserve?","Quer que eu reserve para você?"],["Antes de que alguien se me adelante","Antes que alguém passe na minha frente"],["Me da pena que se acabe el viaje","Me dá pena que a viagem acabe"],["Me molesta que la gente grite","Me incomoda que as pessoas gritem"],
   ["Es lógico que estés cansada","É lógico que você esteja cansada"],["Lo mejor es que descanses","O melhor é que você descanse"],["No es seguro que abran mañana","Não é certo que abram amanhã"],["Quizás llueva por la tarde","Talvez chova de tarde"],["Me encanta que lo veas así","Adoro que você veja assim"],["Esa es la actitud","Essa é a atitude"]
  ]},
{ n:4, me:"A", pv:["m","f"], title:"En primer lugar…", sub:"Argumentar com estrutura e conectores formais",
  tip:`<h3>Construir um argumento</h3>
  <p>Abrir: <b>en primer lugar</b>, <b>para empezar</b>, <b>antes de nada</b>. Acrescentar: <b>además</b>, <b>asimismo</b>, <b>por otro lado</b>, <b>cabe destacar que</b>. Contrastar: <b>sin embargo</b>, <b>no obstante</b>, <b>en cambio</b>, <b>ahora bien</b>, <b>si bien</b>. Causa e consequência: <b>puesto que</b>, <b>dado que</b>, <b>por lo tanto</b>, <b>de ahí que</b> (+ subjuntivo), <b>en consecuencia</b>. Fechar: <b>en definitiva</b>, <b>en resumen</b>, <b>a fin de cuentas</b>.</p>
  <p>Matizar: <b>hasta cierto punto</b>, <b>en cierto modo</b>, <b>no deja de ser</b> (não deixa de ser), <b>por lo general</b>, <b>salvo</b> (exceto).</p>
  <p>Exemplificar: <b>por ejemplo</b>, <b>es decir</b>, <b>esto es</b>, <b>a saber</b>, <b>pongamos por caso</b>.</p>
  <p>Discordar com elegância: <i>Entiendo tu punto de vista, <b>sin embargo</b>…</i> · <i><b>No es que</b> no esté de acuerdo, <b>sino que</b>…</i> (subjuntivo depois de 'no es que').</p>`,
  mission:"Defenda em dois minutos de áudio: 'Viajar devagar é melhor que ver muitas cidades'. Use oito conectores diferentes.",
  dialog:[["A","Yo defiendo que es mejor ver pocas ciudades y conocerlas bien. En primer lugar, se descansa más; además, se conoce a la gente del lugar.","Eu defendo que é melhor ver poucas cidades e conhecê-las bem. Em primeiro lugar, descansa-se mais; além disso, conhece-se a gente do lugar."],["B","Entiendo tu punto de vista. Sin embargo, cuando vienes de tan lejos, quieres aprovechar al máximo.","Entendo seu ponto de vista. No entanto, quando se vem de tão longe, quer-se aproveitar ao máximo."],["A","Ahora bien, ¿aprovechar es ver diez ciudades desde la ventanilla de un tren?","Agora bem, aproveitar é ver dez cidades da janela de um trem?"],["B","No es que no esté de acuerdo, sino que cada viaje es distinto. En cambio, un primer viaje pide variedad.","Não é que eu não concorde, mas é que cada viagem é diferente. Em contrapartida, uma primeira viagem pede variedade."],["A","Hasta cierto punto. Dado que el tiempo es limitado, yo elegiría tres ciudades y las haría a fondo.","Até certo ponto. Dado que o tempo é limitado, eu escolheria três cidades e as faria a fundo."],["B","Puesto que no nos vamos a convencer, te propongo un trato: cinco ciudades, dos noches en cada una.","Já que não vamos nos convencer, proponho um acordo: cinco cidades, duas noites em cada."],["A","En definitiva, un término medio. Acepto.","Em suma, um meio-termo. Aceito."]],
  meB:"A", dialogB:[["A","Quería plantearle una cuestión sobre el presupuesto del proyecto.","Queria colocar uma questão sobre o orçamento do projeto."],["B","Adelante, la escucho.","Prossiga, estou ouvindo."],["A","Para empezar, los costes de transporte han subido un veinte por ciento. Por lo tanto, el margen previsto ya no es realista.","Para começar, os custos de transporte subiram vinte por cento. Portanto, a margem prevista já não é realista."],["B","Soy consciente. No obstante, el cliente no aceptará una subida de precio ahora.","Estou ciente. Não obstante, o cliente não aceitará um aumento de preço agora."],["A","De ahí que proponga renegociar los plazos en lugar del precio. Es decir, entregar en dos fases.","Daí eu propor renegociar os prazos em vez do preço. Ou seja, entregar em duas fases."],["B","Cabe destacar que eso también reduce nuestro riesgo. Prepare una propuesta por escrito.","Cabe destacar que isso também reduz nosso risco. Prepare uma proposta por escrito."],["A","Se la envío esta tarde. A fin de cuentas, es lo que conviene a ambas partes.","Envio hoje à tarde. No fim das contas, é o que convém a ambas as partes."]],
  cards:[
   ["En primer lugar, se descansa más","Em primeiro lugar, descansa-se mais"],["Además, se conoce a la gente del lugar","Além disso, conhece-se a gente do lugar"],["Sin embargo, el tiempo es limitado","No entanto, o tempo é limitado"],["No obstante, el cliente no aceptará","Não obstante, o cliente não aceitará"],["En cambio, un primer viaje pide variedad","Em contrapartida, uma primeira viagem pede variedade"],
   ["Ahora bien, ¿eso es aprovechar?","Agora bem, isso é aproveitar?"],["Dado que el tiempo es limitado…","Dado que o tempo é limitado…"],["Puesto que no nos vamos a convencer…","Já que não vamos nos convencer…"],["Por lo tanto, el margen ya no es realista","Portanto, a margem já não é realista"],["De ahí que proponga renegociar","Daí eu propor renegociar","'De ahí que' pede subjuntivo."],
   ["Es decir, entregar en dos fases","Ou seja, entregar em duas fases"],["Cabe destacar que reduce el riesgo","Cabe destacar que reduz o risco"],["Hasta cierto punto, tienes razón","Até certo ponto, você tem razão"],["No es que no esté de acuerdo, sino que…","Não é que eu não concorde, mas é que…"],["Entiendo tu punto de vista","Entendo seu ponto de vista"],
   ["En definitiva, un término medio","Em suma, um meio-termo"],["A fin de cuentas, es lo que conviene","No fim das contas, é o que convém"],["En resumen, cinco ciudades","Em resumo, cinco cidades"],["Quería plantearle una cuestión","Queria colocar uma questão para o senhor"],["Adelante, le escucho","Prossiga, estou ouvindo"],
   ["Soy consciente de ello","Estou ciente disso"],["Te propongo un trato","Proponho um acordo"],["Por lo general, funciona","Em geral, funciona"],["Salvo excepciones, se cumple","Salvo exceções, cumpre-se"],["No deja de ser una opción","Não deixa de ser uma opção"],["Pongamos por caso que llueve","Suponhamos que chova"]
  ]},
{ n:5, me:"B", pv:["f","m"], title:"Es broma, hombre", sub:"Humor, ironia e segundo sentido",
  tip:`<h3>Entender a piada espanhola</h3>
  <p>O humor espanhol é <b>irônico e autodepreciativo</b>, muito baseado em exagero. Sinais: <i>¡Hombre, claro!</i> (óbvio que não), <i>No, si yo encantado…</i> (dito com cara de desgosto), <i>Qué bien, otra reunión</i>.</p>
  <p>Marcadores: <b>es broma</b> / <b>era broma</b> (brincadeira), <b>en serio</b> (sério), <b>me estás vacilando</b> (está me zoando), <b>no me tomes el pelo</b> (não me faça de bobo), <b>tiene guasa</b> (tem graça / é irônico), <b>con cariño</b> (sem maldade), <b>vaya tela</b> (que coisa).</p>
  <p>Exagero: <b>me muero</b> (de risa, de hambre), <b>me parto</b> (morro de rir), <b>estoy muerta</b> (exausta), <b>un montón</b>, <b>mogollón</b> (muitíssimo, coloquial), <b>ni de broma</b> (nem brincando), <b>ni loco</b> (nem morto).</p>
  <p>Resposta a elogio: espanhóis desviam com humor. <i>— Qué bien hablas. — Es que el vino ayuda.</i></p>`,
  mission:"Responda a três elogios com humor espanhol e conte uma situação embaraçosa da viagem rindo de si mesma.",
  dialog:[["A","¡Qué bien hablas español ya! Pareces de aquí.","Como você fala bem espanhol já! Parece daqui."],["B","Sí, sí, de aquí al lado: de Portugal. Es broma. Es que después de dos cañas me suelto.","Sim, sim, daqui do lado: de Portugal. Brincadeira. É que depois de dois chopes eu me solto."],["A","Pues te invito a la tercera, a ver si te sale el acento de Cádiz.","Então te ofereço o terceiro, para ver se sai o sotaque de Cádiz."],["B","Ni de broma. Con la tercera me sale el portugués y el brasileño a la vez.","Nem brincando. Com o terceiro sai o português e o brasileiro ao mesmo tempo."],["A","Me estás vacilando. Ayer te oí discutir con el taxista como una madrileña.","Está me zoando. Ontem te ouvi discutir com o taxista como uma madrilena."],["B","Eso no era español, era desesperación. Nos cobró el doble.","Aquilo não era espanhol, era desespero. Ele cobrou o dobro."],["A","Vaya tela. Pues esta ronda la pago yo, en serio.","Que coisa. Então esta rodada eu pago, sério."]],
  meB:"B", dialogB:[["A","¿Qué tal la excursión de ayer a Montserrat?","Como foi o passeio de ontem a Montserrat?"],["B","Estupenda. Solo llovió ocho horas de las nueve. Y yo con sandalias.","Ótimo. Só choveu oito das nove horas. E eu de sandálias."],["A","Me parto. ¿Y las vistas?","Morro de rir. E as vistas?"],["B","Preciosas, según la foto de la postal que compré. En directo vi una nube muy bonita.","Lindas, segundo a foto do cartão-postal que comprei. Ao vivo vi uma nuvem muito bonita."],["A","Tiene guasa que el día más lluvioso del año te toque a ti.","Tem graça que o dia mais chuvoso do ano caia justo em você."],["B","Es mi superpoder. Allá donde voy, llevo la lluvia. Deberían pagarme los agricultores.","É meu superpoder. Aonde vou, levo a chuva. Os agricultores deveriam me pagar."],["A","Pues mañana vienes a la playa conmigo. Con cariño: trae paraguas.","Então amanhã você vem à praia comigo. Sem maldade: traga guarda-chuva."]],
  cards:[
   ["Es broma","É brincadeira"],["En serio","Sério"],["Me estás vacilando","Você está me zoando"],["No me tomes el pelo","Não me faça de bobo"],["Tiene guasa","Tem graça, é irônico"],
   ["Vaya tela","Que coisa, inacreditável"],["Con cariño","Sem maldade, com carinho"],["Me parto de risa","Morro de rir"],["Me muero de hambre","Estou morrendo de fome"],["Estoy muerta","Estou exausta"],
   ["Ni de broma","Nem brincando"],["Ni loco","Nem morto"],["Un montón","Um monte"],["Mogollón de gente","Gente demais","Coloquial."],["Después de dos cañas me suelto","Depois de dois chopes eu me solto"],
   ["A ver si te sale el acento","Para ver se sai o sotaque"],["Nos cobró el doble","Cobrou o dobro de nós"],["Esta ronda la pago yo","Esta rodada eu pago"],["Solo llovió ocho horas de nueve","Só choveu oito horas de nove"],["Es mi superpoder","É meu superpoder"],
   ["¡Hombre, claro!","Óbvio! (irônico, muitas vezes = claro que não)"],["Qué bien, otra reunión","Que ótimo, outra reunião (irônico)"],["No, si yo encantado","Não, eu adoro (dito sem adorar)"],["Qué gracioso","Que engraçado"],["No tiene gracia","Não tem graça"],["Me has pillado","Você me pegou"]
  ]},
{ n:6, me:"A", pv:["f","m"], title:"Le escribo en relación con…", sub:"Registro formal: e-mails, telefone e usted",
  tip:`<h3>Formal sem parecer robô</h3>
  <p>E-mail: <b>Estimado/a señor/a</b> (ou <i>Estimada Sra. García</i>), <b>Le escribo en relación con…</b>, <b>Me dirijo a usted para…</b>, <b>Adjunto le envío…</b>, <b>Quedo a su disposición</b>, <b>A la espera de su respuesta</b>, <b>Un cordial saludo</b> / <b>Atentamente</b>. Para pedir: <b>Le agradecería que me confirmara…</b> (condicional + imperfecto de subjuntivo).</p>
  <p>Telefone: <i>Buenos días, llamo de parte de… / Quería hablar con… / ¿Podría ponerme con…?</i> (pode me passar para…) <i>/ ¿De parte de quién? / Ahora mismo le paso / No se retire / Le vuelvo a llamar</i>.</p>
  <p>Usted obriga 3ª pessoa também nos pronomes: <b>le, se, su</b>: <i>Le envío su factura. ¿Se encuentra bien?</i></p>
  <p>Cuidado com falsos formais: <b>ordenador</b> (computador), <b>factura</b> (nota fiscal), <b>presupuesto</b> (orçamento), <b>plazo</b> (prazo), <b>recibo</b>, <b>abonar</b> (pagar), <b>subsanar</b> (corrigir), <b>tramitar</b>.</p>`,
  mission:"Escreva um e-mail formal de oito linhas pedindo o reembolso de um ingresso. Depois leia em voz alta com entonação de telefone.",
  dialog:[["A","Buenos días, llamo en relación con una reserva cancelada. Quería hablar con el departamento de reembolsos.","Bom dia, ligo em relação a uma reserva cancelada. Queria falar com o departamento de reembolsos."],["B","Buenos días. ¿De parte de quién, por favor?","Bom dia. Quem fala, por favor?"],["A","De Ana Souza. El número de reserva es el 4471.","Ana Souza. O número da reserva é 4471."],["B","Un momento, no se retire. Le paso con mi compañera.","Um momento, não desligue. Vou passar para minha colega."],["A","Gracias. Le agradecería que me confirmaran el plazo del reembolso por correo.","Obrigada. Agradeceria que me confirmassem o prazo do reembolso por e-mail."],["B","Por supuesto. Suele tardar entre siete y diez días hábiles. Le envío la confirmación ahora mismo.","Claro. Costuma demorar entre sete e dez dias úteis. Envio a confirmação agora mesmo."],["A","Perfecto. Quedo a la espera. Muy amable.","Perfeito. Fico no aguardo. Muito gentil."]],
  meB:"A", dialogB:[["A","Buenas tardes, soy la inquilina del segundo B. Le escribí la semana pasada por la humedad del baño.","Boa tarde, sou a inquilina do segundo B. Escrevi para o senhor na semana passada pela umidade do banheiro."],["B","Sí, recibí su correo. Disculpe la demora; el fontanero no podía venir antes.","Sim, recebi seu e-mail. Desculpe a demora; o encanador não podia vir antes."],["A","Lo entiendo, pero la mancha ha crecido y ya huele. Le ruego que lo solucione esta semana.","Entendo, mas a mancha cresceu e já cheira mal. Peço que resolva esta semana."],["B","Tiene usted razón. Le confirmo la visita para el jueves por la mañana. ¿Le viene bien?","A senhora tem razão. Confirmo a visita para quinta de manhã. Fica bom?"],["A","Me viene bien. Le agradecería que me avisaran con una hora de antelación.","Fica bom. Agradeceria que me avisassem com uma hora de antecedência."],["B","Así se hará. Y le pido disculpas de nuevo por las molestias.","Assim será feito. E peço desculpas de novo pelo incômodo."],["A","No se preocupe. Quedo a su disposición. Hasta el jueves.","Não se preocupe. Fico à disposição. Até quinta."]],
  cards:[
   ["Estimada señora García:","Prezada senhora García:"],["Le escribo en relación con mi reserva","Escrevo em relação à minha reserva"],["Me dirijo a usted para solicitar un reembolso","Dirijo-me ao senhor para solicitar um reembolso"],["Adjunto le envío la factura","Em anexo envio a nota fiscal"],["Le agradecería que me confirmara el plazo","Agradeceria que me confirmasse o prazo"],
   ["Quedo a su disposición","Fico à sua disposição"],["A la espera de su respuesta","No aguardo de sua resposta"],["Un cordial saludo","Cordiais saudações"],["Atentamente","Atenciosamente"],["Le ruego que lo solucione esta semana","Peço que resolva esta semana"],
   ["Llamo en relación con una reserva cancelada","Ligo em relação a uma reserva cancelada"],["¿De parte de quién?","Quem fala? (da parte de quem)"],["¿Podría ponerme con el departamento de reservas?","Poderia me passar para o departamento de reservas?"],["No se retire, le paso","Não desligue, vou passar"],["Le vuelvo a llamar más tarde","Ligo de novo mais tarde"],
   ["Suele tardar diez días hábiles","Costuma demorar dez dias úteis"],["Disculpe la demora","Desculpe a demora"],["Le pido disculpas por las molestias","Peço desculpas pelo incômodo"],["¿Le viene bien el jueves?","Quinta fica bom para o senhor?"],["Así se hará","Assim será feito"],
   ["Necesito el presupuesto por escrito","Preciso do orçamento por escrito"],["¿Cuál es el plazo de entrega?","Qual é o prazo de entrega?"],["Hay que abonar el importe por adelantado","É preciso pagar o valor adiantado"],["Deben subsanar el error","Devem corrigir o erro"],["Estamos tramitando su solicitud","Estamos processando sua solicitação"],["Le confirmo la cita por correo","Confirmo a consulta por e-mail"]
  ]},
{ n:7, me:"A", pv:["m","f"], title:"¿Cuál es su mejor precio?", sub:"Negociar, persuadir e fechar acordos",
  tip:`<h3>Negociar à espanhola</h3>
  <p>Na Espanha não se regateia no supermercado nem no restaurante, mas sim em mercados de rua, aluguéis, carros e serviços. Abra com interesse, não com ataque: <i>Me interesa, pero <b>se me va de presupuesto</b></i> (sai do meu orçamento).</p>
  <p>Fórmulas: <b>¿Cuál es su mejor precio?</b> · <b>¿Me lo puede dejar en…?</b> (deixa por…) · <b>Si me lleva dos, ¿me hace un descuento?</b> · <b>¿Y si lo pago en efectivo?</b> · <b>Lo dejamos en…</b> (fechamos em…) · <b>Trato hecho</b>.</p>
  <p>Persuadir: <b>le conviene</b> (convém ao senhor), <b>a largo plazo</b>, <b>sale a cuenta</b> (compensa), <b>no se arrepentirá</b>, <b>le garantizo que</b>. Ceder com elegância: <b>está bien, pero</b>, <b>hagamos una cosa</b>, <b>le propongo lo siguiente</b>.</p>
  <p>Recusar: <b>no me compensa</b>, <b>me lo voy a pensar</b> (vou pensar), <b>lo consulto y le digo</b>, <b>se lo agradezco, pero no</b>.</p>`,
  mission:"Negocie em voz alta o preço de um aluguel de carro por uma semana: duas contrapropostas e um fechamento.",
  dialog:[["A","Me interesa el coche, pero trescientos euros la semana se me va de presupuesto. ¿Cuál es su mejor precio?","Me interessa o carro, mas trezentos euros por semana sai do meu orçamento. Qual é o seu melhor preço?"],["B","Es temporada alta. Puedo dejárselo en doscientos ochenta con el seguro básico.","É alta temporada. Posso deixar por duzentos e oitenta com o seguro básico."],["A","¿Y si lo alquilo diez días en vez de siete?","E se eu alugar por dez dias em vez de sete?"],["B","Entonces le sale a cuenta: diez días por trescientos cincuenta, con seguro completo.","Então compensa para a senhora: dez dias por trezentos e cinquenta, com seguro completo."],["A","Hagamos una cosa: trescientos treinta, en efectivo, y lo devuelvo con el depósito lleno.","Vamos fazer assim: trezentos e trinta, em dinheiro, e devolvo com o tanque cheio."],["B","Está bien, pero le garantizo que es el precio más bajo que he hecho este mes.","Está bem, mas garanto que é o preço mais baixo que fiz este mês."],["A","Trato hecho. No se arrepentirá: conduzco mejor que aparco.","Negócio fechado. Não vai se arrepender: dirijo melhor do que estaciono."]],
  meB:"A", dialogB:[["A","El piso me gusta mucho, pero el alquiler está por encima de lo que pagan en la zona.","Gosto muito do apartamento, mas o aluguel está acima do que pagam na região."],["B","Es que está reformado y tiene terraza. Eso se paga.","É que está reformado e tem varanda. Isso se paga."],["A","Lo entiendo. Le propongo lo siguiente: ochocientos cincuenta, con contrato de dos años y pago puntual.","Entendo. Proponho o seguinte: oitocentos e cinquenta, com contrato de dois anos e pagamento pontual."],["B","Dos años me interesa, no voy a negarlo. ¿Y la fianza?","Dois anos me interessa, não vou negar. E o depósito?"],["A","Dos meses, como marca la ley. Y me hago cargo de los pequeños arreglos.","Dois meses, como marca a lei. E eu me encarrego dos pequenos consertos."],["B","A largo plazo me conviene. Lo dejamos en ochocientos setenta y firmamos el lunes.","A longo prazo me convém. Fechamos em oitocentos e setenta e assinamos na segunda."],["A","Me lo voy a pensar esta noche, pero creo que tenemos un acuerdo.","Vou pensar esta noite, mas acho que temos um acordo."]],
  cards:[
   ["Se me va de presupuesto","Sai do meu orçamento"],["¿Cuál es su mejor precio?","Qual é o seu melhor preço?"],["¿Me lo puede dejar en doscientos?","Pode deixar por duzentos?"],["¿Y si lo pago en efectivo?","E se eu pagar em dinheiro?"],["Si me llevo dos, ¿me hace un descuento?","Se eu levar dois, me faz um desconto?"],
   ["Es temporada alta","É alta temporada"],["Le sale a cuenta","Compensa para o senhor"],["Hagamos una cosa","Vamos fazer assim"],["Le propongo lo siguiente","Proponho o seguinte"],["Lo dejamos en trescientos treinta","Fechamos em trezentos e trinta"],
   ["Trato hecho","Negócio fechado"],["Le garantizo que es el precio más bajo","Garanto que é o preço mais baixo"],["No se arrepentirá","Não vai se arrepender"],["Le conviene a largo plazo","Convém ao senhor a longo prazo"],["Está por encima de lo que pagan en la zona","Está acima do que pagam na região"],
   ["Eso se paga","Isso se paga"],["Me hago cargo de los pequeños arreglos","Eu me encarrego dos pequenos consertos"],["Como marca la ley","Como manda a lei"],["Firmamos el lunes","Assinamos na segunda"],["Me lo voy a pensar","Vou pensar"],
   ["Lo consulto y le digo","Vou consultar e aviso"],["No me compensa","Não compensa para mim"],["Se lo agradezco, pero no","Agradeço, mas não"],["Tenemos un acuerdo","Temos um acordo"],["Lo devuelvo con el depósito lleno","Devolvo com o tanque cheio"],["Conduzco mejor que aparco","Dirijo melhor do que estaciono"]
  ]},
{ n:8, me:"B", pv:["m","f"], title:"España hoy", sub:"Sociedade, política e atualidade sem gafe",
  tip:`<h3>Vocabulário para ler o jornal e seguir uma conversa de bar</h3>
  <p>Estado: <b>comunidades autónomas</b> (17 regiões com governo próprio), <b>el Gobierno</b>, <b>el Congreso</b>, <b>el ayuntamiento</b>, <b>las elecciones</b>, <b>el paro</b> (desemprego), <b>la vivienda</b> (moradia, o tema número um), <b>el alquiler</b>, <b>la sanidad pública</b>, <b>la jubilación</b>, <b>las pensiones</b>, <b>los impuestos</b>, <b>la huelga</b> (greve), <b>la manifestación</b> (manifestação).</p>
  <p>Jornal: <b>titular</b> (manchete), <b>portada</b> (capa), <b>sucesos</b> (polícia), <b>columna de opinión</b>, <b>según fuentes</b>, <b>al cierre de esta edición</b>.</p>
  <p>Temas sensíveis que exigem tato: <b>la independencia de Cataluña</b>, <b>la monarquía</b>, <b>la Guerra Civil</b> e <b>Franco</b>, <b>los toros</b>. Pergunte antes de opinar: <i>¿Y aquí cómo se ve el tema de…?</i></p>
  <p>Idiomas: <b>castellano</b> é como muitos chamam o espanhol; <b>catalán, gallego, euskera</b> são cooficiais. Dizer <i>castellano</i> em Barcelona é um gesto de atenção.</p>`,
  mission:"Leia a capa de um jornal espanhol (El País, El Mundo, La Vanguardia) e resuma três notícias em voz alta.",
  dialog:[["A","¿Qué tal el país? Lo veo todo el día en las noticias con la vivienda.","Como vai o país? Vejo o dia todo nas notícias com a moradia."],["B","Es el gran tema. En Madrid y Barcelona el alquiler se ha disparado y los jóvenes no pueden irse de casa de sus padres.","É o grande tema. Em Madri e Barcelona o aluguel disparou e os jovens não conseguem sair da casa dos pais."],["A","¿Y qué hace el Gobierno?","E o que o Governo faz?"],["B","Discutir con las comunidades autónomas, que son las que tienen las competencias. Aquí casi todo pasa por ahí.","Discutir com as comunidades autônomas, que são as que têm as competências. Aqui quase tudo passa por aí."],["A","En Brasil es parecido con los estados. ¿Y el paro? Antes era altísimo.","No Brasil é parecido com os estados. E o desemprego? Antes era altíssimo."],["B","Ha bajado mucho, pero el paro juvenil sigue siendo de los más altos de Europa.","Caiu muito, mas o desemprego juvenil continua entre os mais altos da Europa."],["A","Pues con la sanidad pública que tenéis, yo me quedaba.","Com a saúde pública que vocês têm, eu ficava."]],
  meB:"B", dialogB:[["A","Perdona la pregunta: ¿y aquí cómo se ve el tema de la independencia?","Desculpa a pergunta: e aqui como se vê o tema da independência?"],["B","Depende de a quién preguntes y en qué mesa estés. Es un tema que divide familias.","Depende de quem você pergunta e em que mesa está. É um tema que divide famílias."],["A","Por eso pregunto antes de opinar. En el hotel hablan catalán entre ellos y castellano conmigo.","Por isso pergunto antes de opinar. No hotel falam catalão entre eles e castelhano comigo."],["B","Eso es lo normal, y que digas 'castellano' se agradece. Aquí las dos lenguas conviven.","Isso é o normal, e dizer 'castelhano' é apreciado. Aqui as duas línguas convivem."],["A","¿Te molesta que hablemos de política?","Te incomoda falarmos de política?"],["B","Al contrario, aquí se habla de política en el bar como del fútbol. Lo que molesta es el que llega con la lección aprendida.","Ao contrário, aqui fala-se de política no bar como de futebol. O que incomoda é quem chega com a lição decorada."],["A","Entonces yo escucho y pago la siguiente ronda.","Então eu escuto e pago a próxima rodada."]],
  cards:[
   ["El alquiler se ha disparado","O aluguel disparou"],["Los jóvenes no pueden irse de casa","Os jovens não conseguem sair de casa"],["La vivienda es el gran tema","A moradia é o grande tema"],["Las comunidades autónomas tienen las competencias","As comunidades autônomas têm as competências"],["El paro ha bajado mucho","O desemprego caiu muito"],
   ["El paro juvenil sigue siendo alto","O desemprego juvenil continua alto"],["La sanidad pública funciona bien","A saúde pública funciona bem"],["Hay huelga de trenes mañana","Tem greve de trens amanhã"],["Hay una manifestación en el centro","Tem uma manifestação no centro"],["Las elecciones son en mayo","As eleições são em maio"],
   ["Los impuestos han subido","Os impostos subiram"],["La edad de jubilación son los 67","A idade de aposentadoria é 67"],["¿Y aquí cómo se ve el tema de…?","E aqui como se vê o tema de…?"],["Es un tema que divide familias","É um tema que divide famílias"],["Depende de a quién preguntes","Depende de quem você pergunta"],
   ["Pregunto antes de opinar","Pergunto antes de opinar"],["Hablan catalán entre ellos y castellano conmigo","Falam catalão entre eles e castelhano comigo"],["Las dos lenguas conviven","As duas línguas convivem"],["Se habla de política como del fútbol","Fala-se de política como de futebol"],["El que llega con la lección aprendida","Quem chega com a lição decorada"],
   ["¿Has leído el titular de hoy?","Você leu a manchete de hoje?"],["Salió en la portada de El País","Saiu na capa do El País"],["Según fuentes del Gobierno","Segundo fontes do Governo"],["Es una columna de opinión, no una noticia","É uma coluna de opinião, não uma notícia"],["El ayuntamiento ha aprobado la medida","A prefeitura aprovou a medida"],["Yo escucho y pago la siguiente ronda","Eu escuto e pago a próxima rodada"]
  ]},
{ n:9, me:"A", pv:["f","m"], title:"De Velázquez a Almodóvar", sub:"Arte, cinema e literatura para conversar",
  tip:`<h3>Cultura para a conversa, não para a prova</h3>
  <p>Pintura: <b>Velázquez</b> (Las Meninas, Prado), <b>Goya</b> (as pinturas negras, os fusilamientos), <b>El Greco</b> (Toledo), <b>Picasso</b> (Guernica, no Reina Sofía), <b>Dalí</b> (Figueres), <b>Miró</b> (Barcelona), <b>Sorolla</b> (a luz de Valência).</p>
  <p>Literatura: <b>Cervantes</b> e o <i>Quijote</i> (1605), <b>Lorca</b> (Granada, fusilado em 1936), <b>Machado</b>, <b>Carmen Laforet</b> (<i>Nada</i>), <b>Javier Marías</b>, <b>Almudena Grandes</b>, <b>Carlos Ruiz Zafón</b> (<i>La sombra del viento</i>, Barcelona).</p>
  <p>Cinema e TV: <b>Almodóvar</b>, <b>Amenábar</b>, <b>Penélope Cruz</b>, <b>Javier Bardem</b>, séries como <i>La casa de papel</i>. Música: <b>Rosalía</b>, <b>Sabina</b>, <b>Serrat</b>, <b>Paco de Lucía</b>, <b>Camarón</b>.</p>
  <p>Falar de obras: <b>me conmovió</b> (me comoveu), <b>está sobrevalorada</b>, <b>es una obra maestra</b>, <b>no me dice nada</b>, <b>engancha</b> (vicia), <b>tiene un final abierto</b>, <b>el protagonista</b>, <b>la trama</b> (o enredo), <b>el doblaje</b> (dublagem; na Espanha quase tudo é dublado).</p>`,
  mission:"Veja um filme de Almodóvar com áudio em espanhol e legendas em espanhol. Resuma a trama em um minuto.",
  dialog:[["A","¿Qué te ha parecido Las Meninas en directo?","O que você achou de Las Meninas ao vivo?"],["B","Me ha dejado clavada. Lo raro es que el cuadro te mira a ti, no al revés.","Me deixou pregada. O estranho é que o quadro olha para você, não o contrário."],["A","Esa es la gracia. Velázquez se pinta a sí mismo pintando, y el rey y la reina aparecen en el espejo del fondo.","Essa é a graça. Velázquez pinta a si mesmo pintando, e o rei e a rainha aparecem no espelho do fundo."],["B","Lo que no esperaba eran las pinturas negras de Goya. Me conmovieron y me asustaron a la vez.","O que eu não esperava eram as pinturas negras de Goya. Me comoveram e me assustaram ao mesmo tempo."],["A","Las pintó en las paredes de su casa, sordo y solo. Nadie las vio en vida de él.","Ele as pintou nas paredes da casa, surdo e sozinho. Ninguém as viu em vida dele."],["B","Pues después de eso, el Guernica mañana me va a destrozar.","Então depois disso, o Guernica amanhã vai me destruir."],["A","Te recomiendo que vayas a primera hora, cuando la sala está vacía. Ahí sí que habla.","Recomendo que vá na primeira hora, quando a sala está vazia. Aí sim ele fala."]],
  meB:"A", dialogB:[["A","Anoche vi una película de Almodóvar en el hotel, pero estaba doblada al inglés. Un crimen.","Ontem à noite vi um filme do Almodóvar no hotel, mas estava dublado em inglês. Um crime."],["B","Aquí es al revés: doblamos todo lo extranjero. Por eso los españoles hablamos tan mal inglés.","Aqui é o contrário: dublamos tudo que é estrangeiro. Por isso os espanhóis falamos inglês tão mal."],["A","¿Cuál me recomiendas para empezar con él?","Qual você recomenda para começar com ele?"],["B","Volver, con Penélope Cruz. Es La Mancha, las madres, los muertos que no se van del todo. Muy español.","Volver, com Penélope Cruz. É La Mancha, as mães, os mortos que não vão de todo embora. Muito espanhol."],["A","¿Y para leer en el tren?","E para ler no trem?"],["B","La sombra del viento, de Ruiz Zafón. Es Barcelona en los años cuarenta y engancha desde la primera página.","La sombra del viento, do Ruiz Zafón. É Barcelona nos anos quarenta e vicia desde a primeira página."],["A","Apuntado. Y con final cerrado, espero, que yo con los finales abiertos sufro.","Anotado. E com final fechado, espero, que eu com finais abertos sofro."]],
  cards:[
   ["Me ha dejado clavada","Me deixou pregada, sem palavras"],["El cuadro te mira a ti","O quadro olha para você"],["Esa es la gracia","Essa é a graça"],["Se pinta a sí mismo pintando","Pinta a si mesmo pintando"],["Me conmovió y me asustó a la vez","Me comoveu e me assustou ao mesmo tempo"],
   ["Nadie las vio en vida de él","Ninguém as viu em vida dele"],["Es una obra maestra","É uma obra-prima"],["Está sobrevalorada","Está superestimada"],["No me dice nada","Não me diz nada"],["Me va a destrozar","Vai me destruir"],
   ["Ve a primera hora, cuando la sala está vacía","Vá na primeira hora, quando a sala está vazia"],["Estaba doblada al inglés","Estava dublada em inglês"],["Aquí doblamos todo lo extranjero","Aqui dublamos tudo que é estrangeiro"],["Prefiero la versión original con subtítulos","Prefiro a versão original com legendas"],["¿Cuál me recomiendas para empezar?","Qual você recomenda para começar?"],
   ["Engancha desde la primera página","Vicia desde a primeira página"],["La trama es complicada","O enredo é complicado"],["El protagonista es un librero","O protagonista é um livreiro"],["Tiene un final abierto","Tem um final aberto"],["Con los finales abiertos sufro","Com finais abertos eu sofro"],
   ["Apuntado","Anotado"],["Lorca nació en Granada","Lorca nasceu em Granada"],["El Quijote es de 1605","O Quixote é de 1605"],["Es un clásico del cine español","É um clássico do cinema espanhol"],["La banda sonora es preciosa","A trilha sonora é linda"],["Fuimos al estreno","Fomos à estreia"]
  ]},
{ n:10, me:"B", pv:["f","m"], title:"A quien madruga…", sub:"Refrões, metáforas e linguagem figurada",
  tip:`<h3>Refrões que todo espanhol completa</h3>
  <p>Diga a primeira metade e um espanhol completa a segunda: <b>A quien madruga…</b> <i>Dios le ayuda</i>. <b>No por mucho madrugar…</b> <i>amanece más temprano</i>. <b>Más vale pájaro en mano…</b> <i>que ciento volando</i>. <b>Ojos que no ven…</b> <i>corazón que no siente</i>. <b>En casa del herrero…</b> <i>cuchillo de palo</i>. <b>Dime con quién andas…</b> <i>y te diré quién eres</i>. <b>A lo hecho, pecho</b>. <b>Quien no llora, no mama</b>.</p>
  <p>Expressões figuradas de uso diário: <b>estar en el quinto pino</b> (muito longe), <b>costar un ojo de la cara</b> (custar os olhos da cara), <b>no tener pelos en la lengua</b> (falar sem rodeios), <b>tirar la casa por la ventana</b> (gastar sem medo), <b>irse por las ramas</b> (fugir do assunto), <b>meter la pata</b> (dar uma gafe), <b>estar como una cabra</b> (ser maluco), <b>ser pan comido</b> (ser moleza), <b>a otra cosa, mariposa</b> (próximo assunto).</p>
  <p>Comida como metáfora: <b>ser un bombón</b>, <b>estar de mala uva</b> (mau humor), <b>importar un pimiento</b> (não importar nada), <b>darle la vuelta a la tortilla</b> (virar o jogo).</p>`,
  mission:"Aprenda cinco refrões de cor e use dois deles numa conversa real ou num áudio para a Lola.",
  dialog:[["A","Mañana madrugamos para la Alhambra. A las siete en pie.","Amanhã acordamos cedo para a Alhambra. Às sete de pé."],["B","A quien madruga, Dios le ayuda. Aunque no por mucho madrugar amanece más temprano.","Quem madruga, Deus ajuda. Embora não é por madrugar muito que amanhece mais cedo."],["A","¡Ya hablas con refranes! Eso es nivel avanzado.","Já fala com refrões! Isso é nível avançado."],["B","Es que ayer metí la pata con el camarero y me dijo 'a lo hecho, pecho'. Lo busqué y me enganché.","É que ontem dei uma gafe com o garçom e ele me disse 'o que está feito, está feito'. Procurei e viciei."],["A","¿Qué le dijiste?","O que você disse para ele?"],["B","Que la tortilla estaba 'muy excitante'. Quería decir 'muy rica'.","Que a tortilla estava 'muito excitante'. Queria dizer 'muito gostosa'."],["A","Me parto. Bueno, a otra cosa, mariposa: ¿llevas las entradas?","Morro de rir. Bom, próximo assunto: você está com os ingressos?"]],
  meB:"B", dialogB:[["A","¿Cuánto os costó el hotel de Barcelona al final?","Quanto custou o hotel de Barcelona no fim?"],["B","Un ojo de la cara. Pero bueno, de vez en cuando hay que tirar la casa por la ventana.","Os olhos da cara. Mas enfim, de vez em quando é preciso gastar sem medo."],["A","¿Y está bien situado?","E é bem localizado?"],["B","Está en el quinto pino, para ser sincera. Media hora de metro hasta el centro.","Fica longe demais, para ser sincera. Meia hora de metrô até o centro."],["A","Pues no tienes pelos en la lengua.","Você não tem papas na língua."],["B","Mi madre siempre dice que dime con quién andas y te diré quién eres. Y yo ando con españoles.","Minha mãe sempre diz que me diga com quem andas e te direi quem és. E eu ando com espanhóis."],["A","Ja, ja. Pues ojos que no ven, corazón que no siente: no mires la factura y disfruta.","Ha, ha. Então o que os olhos não veem, o coração não sente: não olhe a fatura e aproveite."]],
  cards:[
   ["A quien madruga, Dios le ayuda","Quem madruga, Deus ajuda"],["No por mucho madrugar amanece más temprano","Não é por madrugar que amanhece mais cedo"],["Más vale pájaro en mano que ciento volando","Mais vale um pássaro na mão que dois voando"],["Ojos que no ven, corazón que no siente","O que os olhos não veem, o coração não sente"],["En casa del herrero, cuchillo de palo","Em casa de ferreiro, espeto de pau"],
   ["Dime con quién andas y te diré quién eres","Diga-me com quem andas e te direi quem és"],["A lo hecho, pecho","O que está feito, está feito"],["Quien no llora, no mama","Quem não chora, não mama"],["A otra cosa, mariposa","Próximo assunto"],["Está en el quinto pino","Fica longe demais"],
   ["Me costó un ojo de la cara","Me custou os olhos da cara"],["No tiene pelos en la lengua","Não tem papas na língua"],["Tiramos la casa por la ventana","Gastamos sem medo"],["No te vayas por las ramas","Não fuja do assunto"],["Metí la pata","Dei uma gafe"],
   ["Está como una cabra","É maluco"],["Es pan comido","É moleza"],["Está de mala uva","Está de mau humor"],["Me importa un pimiento","Não me importa nada"],["Le dimos la vuelta a la tortilla","Viramos o jogo"],
   ["Es un bombón","É um(a) gato(a)"],["Me enganché a los refranes","Viciei nos refrões"],["Hay que tirar la casa por la ventana de vez en cuando","É preciso gastar sem medo de vez em quando"],["Para ser sincera, está lejos","Para ser sincera, fica longe"],["No mires la factura y disfruta","Não olhe a fatura e aproveite"],["Nivel avanzado","Nível avançado"]
  ]},
{ n:11, me:"A", pv:["m","f"], title:"¿De dónde ere', illo?", sub:"Sotaques e variedades da Espanha",
  tip:`<h3>Um país, muitos espanhóis</h3>
  <p><b>Andaluz</b> (Sevilla, Cádiz, Granada): some o <b>-s</b> final (<i>ere'</i> por eres), <b>-ado → -ao</b> (<i>cansao</i>), o <b>ceceo/seseo</b>, e <b>illo/illa</b> como vocativo (<i>¡Illo!</i>). <i>Quillo</i> = chiquillo. Mais rápido e musical; é o sotaque que mais assusta e mais encanta.</p>
  <p><b>Madrileño/castellano central</b>: pronuncia tudo, <b>-ado</b> vira <i>-ao</i> na fala rápida, usa <b>laísmo</b> (<i>la dije</i> por le dije), e o <b>d</b> final soa como <i>z</i>: <i>Madriz</i>.</p>
  <p><b>Catalán e valenciano</b> influenciam o espanhol da região: <b>l</b> mais grossa, vogais abertas, <i>¿sí o qué?</i>, <i>plegar</i> (sair do trabalho). <b>Gallego</b>: cadência doce, entonação subindo; <i>¿e logo?</i>. <b>Canario</b>: parece caribenho, usa <i>ustedes</i> no lugar de vosotros, <i>guagua</i> = ônibus. <b>Vasco</b>: ritmo forte, <i>pues</i> no fim (<i>no sé, pues</i>), <i>aúpa</i>.</p>
  <p>Estratégia: <i>Perdona, ¿me lo repites? No estoy acostumbrada al acento.</i> Nunca imite por brincadeira; pergunte e elogie.</p>`,
  mission:"Ouça três minutos de um vídeo de alguém de Cádiz e três de alguém de Madri. Anote cinco diferenças que você percebeu.",
  dialog:[["A","Perdona, ¿me lo puedes repetir? No estoy acostumbrada al acento andaluz todavía.","Desculpa, pode repetir? Ainda não estou acostumada com o sotaque andaluz."],["B","Claro, mi arma. Que si queréis la mesa de dentro o la de fuera, que fuera hace fresquito.","Claro, querida. Se vocês querem a mesa de dentro ou a de fora, que fora está fresquinho."],["A","Ah, la de fuera. Es que os coméis las eses y me pierdo.","Ah, a de fora. É que vocês engolem os esses e eu me perco."],["B","Eso dicen los de Madrid, que luego dicen 'Madriz' y 'cansao'. Cada uno tiene lo suyo.","Isso dizem os de Madri, que depois falam 'Madriz' e 'cansao'. Cada um tem o seu."],["A","¿Y 'mi arma' qué es?","E 'mi arma' o que é?"],["B","'Mi alma'. Es cariño, se le dice a todo el mundo. Como 'quillo' o 'illo'.","'Minha alma'. É carinho, diz-se a todo mundo. Como 'quillo' ou 'illo'."],["A","Pues me gusta más que el inglés de Londres, que ese sí que no lo entiendo.","Gosto mais que o inglês de Londres, que esse sim eu não entendo."]],
  meB:"A", dialogB:[["A","En Barcelona me pasó una cosa curiosa: una señora me dijo '¿sí o qué?' al final de cada frase.","Em Barcelona aconteceu uma coisa curiosa: uma senhora dizia '¿sí o qué?' no fim de cada frase."],["B","Es muy típico de allí. Es como el 'pues' que ponemos los vascos al final: 'no sé, pues'.","É muito típico de lá. É como o 'pues' que nós bascos colocamos no fim: 'no sé, pues'."],["A","¿Y en Canarias hablan como en Cuba de verdad?","E nas Canárias falam como em Cuba de verdade?"],["B","Se parece bastante. Dicen 'ustedes' en vez de 'vosotros' y a los autobuses los llaman guaguas.","Parece bastante. Dizem 'ustedes' em vez de 'vosotros' e chamam os ônibus de guaguas."],["A","Entonces el español 'correcto' no existe.","Então o espanhol 'correto' não existe."],["B","Existen muchos y todos son correctos. Lo que no se perdona es imitar el acento para hacer gracia.","Existem muitos e todos são corretos. O que não se perdoa é imitar o sotaque para fazer graça."],["A","Tomo nota. Yo pregunto y me callo, pues.","Anoto. Eu pergunto e me calo, pues."]],
  cards:[
   ["¿Me lo puedes repetir?","Pode repetir?"],["No estoy acostumbrada al acento","Não estou acostumada com o sotaque"],["Os coméis las eses","Vocês engolem os esses"],["Cada uno tiene lo suyo","Cada um tem o seu"],["Mi arma","Querida (andaluz: mi alma)"],
   ["¡Quillo! ¡Illo!","Ei, cara! (andaluz)"],["Hace fresquito","Está fresquinho"],["'Madriz' y 'cansao'","Como os madrilenos falam Madrid e cansado"],["¿Sí o qué?","Não é? (Catalunha)"],["No sé, pues","Não sei, né (País Basco)"],
   ["Aúpa","Força! Olá! (País Basco)"],["La guagua","O ônibus (Canárias)"],["Ustedes en vez de vosotros","Ustedes em vez de vosotros"],["¿E logo?","E então? (Galícia)"],["Plegar del trabajo","Sair do trabalho (Catalunha)"],
   ["El acento andaluz es musical","O sotaque andaluz é musical"],["Hablan más rápido en el sur","Falam mais rápido no sul"],["El español correcto no existe: existen muchos","O espanhol correto não existe: existem muitos"],["No se perdona imitar el acento para hacer gracia","Não se perdoa imitar o sotaque para fazer graça"],["Yo pregunto y me callo","Eu pergunto e me calo"],
   ["Tomo nota","Anoto"],["¿De qué parte de España eres?","De que parte da Espanha você é?"],["Se te nota el acento gallego","Dá para notar seu sotaque galego"],["Me encanta cómo habláis aquí","Adoro como vocês falam aqui"],["En el norte hablan más despacio","No norte falam mais devagar"],["Me pierdo con las eses","Eu me perco com os esses"]
  ]},
{ n:12, me:"B", pv:["m","f"], title:"Flipo, en serio", sub:"Jerga jovem e coloquial de hoje",
  tip:`<h3>Como falam os jovens (e os nem tão jovens)</h3>
  <p><b>Flipar</b> = ficar impressionado (<i>flipo, flipé, es flipante</i>). <b>Molar</b> = ser legal. <b>Currar</b> = trabalhar (<i>el curro</i>). <b>Pasta</b> = dinheiro. <b>Pillar</b> = pegar, entender (<i>no lo pillo</i>). <b>Liarse</b> = complicar-se; também ficar com alguém. <b>Rayarse</b> = ficar pensando demais. <b>Petarlo</b> = arrasar. <b>Ir de</b> = se fazer de (<i>va de listo</i>). <b>Ser un crack</b> = ser fera. <b>Quedar</b> = marcar de se ver. <b>Colega</b> = amigo. <b>Guiri</b> = turista estrangeiro (carinhoso-irônico). <b>Cutre</b> = de má qualidade. <b>Chungo</b> = ruim, difícil. <b>Birra</b> = cerveja. <b>Finde</b> = fim de semana. <b>Tope</b> = muito (<i>tope guay</i>). <b>Literal</b>, <b>en plan</b>, <b>o sea</b> como muletillas.</p>
  <p>Intensificadores: <b>un montón</b>, <b>mazo</b> (Madrid), <b>la leche</b> (<i>es la leche</i> = é demais), <b>de puta madre</b> (vulgar mas comum: ótimo), <b>cojonudo</b> (vulgar: excelente).</p>
  <p>Dica: entenda tudo, use pouco. Um estrangeiro falando jerga demais soa forçado; uma palavra bem colocada soa natural.</p>`,
  mission:"Assista a um vídeo de um youtuber espanhol jovem e anote dez palavras de jerga. Use duas.",
  dialog:[["A","Tía, ¿cómo fue el finde? Vi tus fotos de Cádiz y flipé.","Mina, como foi o finde? Vi suas fotos de Cádiz e fiquei chocada."],["B","Fue la leche. El atardecer en la playa de la Caleta lo petó.","Foi demais. O pôr do sol na praia da Caleta arrasou."],["A","¿Y el hostal? Parecía un poco cutre en la web.","E o hostel? Parecia meio ruinzinho no site."],["B","Cutre pero con encanto. Y por esa pasta, no me rayo.","Ruinzinho mas com charme. E por esse dinheiro, não me estresso."],["A","¿Quedamos este finde y me lo cuentas con una birra?","Marcamos neste finde e você me conta com uma cerveja?"],["B","Vale, pero el viernes curro hasta tarde. ¿El sábado?","Tá, mas sexta trabalho até tarde. Sábado?"],["A","Sábado tope bien. Eres una crack, de verdad.","Sábado super bem. Você é fera, sério."]],
  meB:"B", dialogB:[["A","¿Qué tal con los compañeros nuevos del curro?","Como vai com os novos colegas do trabalho?"],["B","Bien, pero hay uno que va de listo y no lo pillo. Habla en plan jefe sin ser jefe.","Bem, mas tem um que se faz de esperto e não entendo. Fala tipo chefe sem ser chefe."],["A","Pasa de él. Lo chungo sería que fuera tu jefe de verdad.","Ignora ele. O ruim seria que fosse seu chefe de verdade."],["B","Literal. Lo demás mola mazo: horario flexible y los viernes acabamos a las tres.","Literalmente. O resto é muito legal: horário flexível e às sextas acabamos às três."],["A","Eso es de puta madre, perdona la expresión.","Isso é ótimo, desculpa a expressão."],["B","Aquí la dice hasta mi abuela. ¿Te vienes el viernes a tomar algo con los colegas?","Aqui até minha avó diz. Você vem na sexta tomar algo com os colegas?"],["A","Me apunto. Y guiri yo, que lo sepan: pido el menú en inglés para que se rían.","Tô dentro. E guiri eu, que saibam: peço o cardápio em inglês para rirem."]],
  cards:[
   ["Flipo","Fico chocado, impressionado"],["Es flipante","É impressionante"],["Mola mucho","É muito legal"],["Mola mazo","É legal demais (Madri)"],["Curro hasta tarde","Trabalho até tarde"],
   ["El curro","O trabalho"],["No tengo pasta","Não tenho dinheiro"],["No lo pillo","Não entendo, não pego"],["Me he liado","Me enrolei, me confundi"],["No te rayes","Não fique se estressando"],
   ["Lo petó","Arrasou"],["Va de listo","Se faz de esperto"],["Eres un crack","Você é fera"],["¿Quedamos el sábado?","Marcamos sábado?","'Quedar' = marcar encontro."],["Mis colegas","Meus amigos"],
   ["Los guiris","Os turistas estrangeiros"],["Es un poco cutre","É meio ruinzinho, barato"],["Qué chungo","Que ruim, que difícil"],["Una birra","Uma cerveja"],["Este finde","Este fim de semana"],
   ["Tope guay","Super legal"],["Es la leche","É demais"],["Literal","Literalmente (muletilla)"],["Pasa de él","Ignora ele"],["Me apunto","Tô dentro"],["Perdona la expresión","Desculpa a expressão"]
  ]},
{ n:13, me:"A", pv:["f","m"], title:"Y entonces, no te lo vas a creer…", sub:"Contar uma anedota com graça",
  tip:`<h3>A arte de contar</h3>
  <p>Toda boa história espanhola tem gancho: <b>No te lo vas a creer</b>, <b>¿Sabes lo que me pasó?</b>, <b>Resulta que…</b> (acontece que), <b>Pues verás…</b></p>
  <p>Presente histórico para dar vida: <i>Y entonces <b>entra</b> el camarero y me <b>dice</b>…</i> Diálogo citado: <i>Y yo: «¿perdón?» Y él: «que son treinta euros».</i> Reações do ouvinte: <b>¡No me digas!</b>, <b>¡Anda ya!</b> (não acredito), <b>¿En serio?</b>, <b>¡Qué fuerte!</b>, <b>¡Venga ya!</b>, <b>¿Y qué hiciste?</b></p>
  <p>Ritmo: <b>de pronto</b>, <b>en ese momento</b>, <b>para colmo</b> (para completar), <b>encima</b> (ainda por cima), <b>menos mal que</b> (ainda bem que), <b>al final</b>, <b>moraleja</b> (moral da história).</p>
  <p>Exagero controlado é parte do estilo: <i>había como mil personas</i>, <i>tardó tres horas</i> (eram dez minutos).</p>`,
  mission:"Grave a melhor anedota da sua vida em espanhol, três minutos, com gancho, presente histórico, diálogo citado e moral.",
  dialog:[["A","¿Sabes lo que me pasó ayer en el AVE? No te lo vas a creer.","Sabe o que aconteceu comigo ontem no AVE? Você não vai acreditar."],["B","Cuenta.","Conta."],["A","Resulta que me siento, saco el bocadillo, y entra un señor con un jamón entero. Un jamón. Con pata.","Acontece que eu sento, tiro o sanduíche, e entra um senhor com um presunto inteiro. Um presunto. Com pata."],["B","¡Anda ya!","Não acredito!"],["A","Te lo juro. Lo pone en el asiento de al lado, le abrocha el cinturón y me dice: «Es que es de Jabugo, no me fío de la maleta».","Juro. Ele coloca no assento ao lado, prende o cinto e me diz: «É que é de Jabugo, não confio na mala»."],["B","¡Qué fuerte! ¿Y qué hiciste?","Que loucura! E o que você fez?"],["A","Pues verás: al final me ofreció una loncha. Moraleja: en España hasta el jamón viaja en primera.","Pois veja: no fim ele me ofereceu uma fatia. Moral da história: na Espanha até o presunto viaja na primeira classe."]],
  meB:"A", dialogB:[["A","Espera, que la mía es mejor. Resulta que anoche pedimos la cuenta y el camarero trae una de ciento ochenta euros.","Espera, que a minha é melhor. Acontece que ontem à noite pedimos a conta e o garçom traz uma de cento e oitenta euros."],["B","¿Por cuatro tapas?","Por quatro tapas?"],["A","Eso dije yo. Y él: «Es la mesa doce». Y yo: «Somos la dos». Para colmo, en la mesa doce había una despedida de soltera.","Isso eu disse. E ele: «É a mesa doze». E eu: «Somos a dois». Para completar, na mesa doze tinha uma despedida de solteira."],["B","¡Venga ya! ¿Y entonces?","Não me diga! E então?"],["A","Encima la novia se acerca y me dice: «¡Qué detalle, invitarnos!». Menos mal que el dueño lo vio todo.","Ainda por cima a noiva se aproxima e me diz: «Que gentileza, nos pagar!». Ainda bem que o dono viu tudo."],["B","Me muero. ¿Pagasteis al final?","Morro. Vocês pagaram no fim?"],["A","Veintidós euros y un chupito de regalo por el susto. En ese momento decidí que amo este país.","Vinte e dois euros e um shot de presente pelo susto. Nesse momento decidi que amo este país."]],
  cards:[
   ["No te lo vas a creer","Você não vai acreditar"],["¿Sabes lo que me pasó?","Sabe o que aconteceu comigo?"],["Resulta que…","Acontece que…"],["Pues verás…","Pois veja…"],["Te lo juro","Juro"],
   ["Y entonces entra el camarero y me dice…","E então entra o garçom e me diz…","Presente histórico."],["Y yo: «¿perdón?»","E eu: «perdão?»"],["¡No me digas!","Não me diga!"],["¡Anda ya!","Não acredito!"],["¡Venga ya!","Para com isso! Não me diga!"],
   ["¿En serio?","Sério?"],["¿Y qué hiciste?","E o que você fez?"],["De pronto, se apagan las luces","De repente, apagam-se as luzes"],["En ese momento decidí que amo este país","Nesse momento decidi que amo este país"],["Para colmo, empezó a llover","Para completar, começou a chover"],
   ["Encima, la novia se acerca","Ainda por cima, a noiva se aproxima"],["Menos mal que el dueño lo vio","Ainda bem que o dono viu"],["Al final me ofreció una loncha","No fim me ofereceu uma fatia"],["Moraleja: hasta el jamón viaja en primera","Moral da história: até o presunto viaja na primeira classe"],["Había como mil personas","Tinha tipo mil pessoas"],
   ["Me muero","Morro (de rir, de vergonha)"],["Espera, que la mía es mejor","Espera, que a minha é melhor"],["Un chupito de regalo","Um shot de presente"],["Por el susto","Pelo susto"],["No me fío de la maleta","Não confio na mala"],["Es de Jabugo","É de Jabugo (o melhor presunto)"]
  ]},
{ n:14, me:"B", pv:["f","f"], title:"Hablar como de aquí", sub:"Ritmo, entonação e os últimos detalhes",
  tip:`<h3>O que separa o avançado do nativo</h3>
  <p><b>Ritmo silábico</b>: o espanhol dá quase o mesmo tempo a cada sílaba, sem as vogais reduzidas do português. <i>Te-lé-fo-no</i>, nunca "tlefnu". Vogais sempre abertas e claras: <b>e</b> nunca vira <i>i</i>, <b>o</b> nunca vira <i>u</i>.</p>
  <p><b>Entonação</b>: a pergunta sim/não sobe no fim; a pergunta com <i>qué, dónde, cuándo</i> desce. A afirmação é plana e cai. Espanhóis falam em blocos rápidos com pausas curtas, não alongam.</p>
  <p><b>Ligações</b>: <i>los amigos</i> soa "lo-sa-mi-gos"; <i>¿Cómo estás?</i> soa "co-moes-tás". A consoante final gruda na vogal seguinte.</p>
  <p><b>Detalhes que delatam</b>: dizer "muito" (<i>mucho</i>), "pero" com erre vibrado (<i>pero</i> tem erre simples; <i>perro</i>, duplo), "Madrid" com <i>i</i> final arrastado, "e" no lugar de <i>y</i>. E nunca "cola" por fila de pessoas em sentido vulgar... <i>cola</i> está certo!</p>
  <p>Último conselho: <b>hable con las manos y mire a los ojos</b>. Metade da conversa espanhola é gesto e presença.</p>`,
  mission:"Grave-se lendo a leitura de hoje em velocidade natural. Compare com o áudio da Elvira. Repita até a entonação coincidir.",
  dialog:[["A","Después de catorce temas, ¿qué es lo que más te ha costado?","Depois de catorze temas, o que foi mais difícil para você?"],["B","El ritmo. Yo alargaba las vocales como en portugués y aquí todo es más seco, más rápido.","O ritmo. Eu alongava as vogais como em português e aqui tudo é mais seco, mais rápido."],["A","Y ya no dices 'muito'. Eso es un hito.","E você já não diz 'muito'. Isso é um marco."],["B","Casi. Se me escapa cuando me emociono. Y el 'pero' con erre fuerte, que me sale 'perro'.","Quase. Escapa quando me emociono. E o 'pero' com erre forte, que me sai 'perro'."],["A","Eso a los españoles nos hace gracia, no te preocupes. ¿Y lo que mejor llevas?","Isso para nós espanhóis é engraçado, não se preocupe. E o que você leva melhor?"],["B","El subjuntivo. Me da miedo decirlo en voz alta, pero ya ni lo pienso.","O subjuntivo. Tenho medo de dizer em voz alta, mas já nem penso nele."],["A","Pues entonces ya hablas como de aquí. Lo que te queda es seguir viviendo en español.","Então você já fala como daqui. O que falta é continuar vivendo em espanhol."]],
  meB:"A", dialogB:[["A","¿Me notas el acento brasileño todavía?","Você ainda percebe meu sotaque brasileiro?"],["B","Un poquito en las vocales, pero es un acento precioso. Lo que te delata es otra cosa.","Um pouquinho nas vogais, mas é um sotaque lindo. O que te delata é outra coisa."],["A","¿Qué?","O quê?"],["B","Que pides perdón demasiado. Los españoles no pedimos perdón por preguntar ni por pedir la cuenta.","Que você pede desculpa demais. Nós espanhóis não pedimos desculpa por perguntar nem por pedir a conta."],["A","Es verdad. Y hablo más bajo que vosotros.","É verdade. E falo mais baixo que vocês."],["B","Eso tiene arreglo: dos cañas y una terraza. Y mirar a los ojos cuando hablas, que eso aquí es confianza.","Isso tem solução: dois chopes e um terraço. E olhar nos olhos quando fala, que isso aqui é confiança."],["A","Entonces mañana me oirás desde la otra acera.","Então amanhã você vai me ouvir do outro lado da rua."]],
  cards:[
   ["¿Qué es lo que más te ha costado?","O que foi mais difícil para você?"],["El ritmo: aquí todo es más seco","O ritmo: aqui tudo é mais seco"],["Alargaba las vocales como en portugués","Alongava as vogais como em português"],["Eso es un hito","Isso é um marco"],["Se me escapa cuando me emociono","Escapa quando me emociono"],
   ["Me sale 'perro' en vez de 'pero'","Me sai 'perro' em vez de 'pero'"],["Eso nos hace gracia","Isso nos diverte"],["Ya ni lo pienso","Já nem penso nisso"],["Ya hablas como de aquí","Já fala como daqui"],["Seguir viviendo en español","Continuar vivendo em espanhol"],
   ["¿Me notas el acento?","Você percebe meu sotaque?"],["Un poquito en las vocales","Um pouquinho nas vogais"],["Lo que te delata es otra cosa","O que te delata é outra coisa"],["Pides perdón demasiado","Você pede desculpa demais"],["Hablo más bajo que vosotros","Falo mais baixo que vocês"],
   ["Eso tiene arreglo","Isso tem solução"],["Mirar a los ojos es confianza","Olhar nos olhos é confiança"],["Me oirás desde la otra acera","Vai me ouvir do outro lado da rua"],["Hablar con las manos","Falar com as mãos"],["Las vogales siempre abiertas y claras","As vogais sempre abertas e claras"],
   ["La pregunta sube al final","A pergunta sobe no fim"],["Hablamos en bloques rápidos","Falamos em blocos rápidos"],["La consonante se pega a la vocal siguiente","A consoante gruda na vogal seguinte"],["Catorce temas después","Catorze temas depois"],["Lo has conseguido","Você conseguiu"],["¡Enhorabuena!","Parabéns!"]
  ]}
];
