const PEGADINHAS_B2 = [
  {t:"Había llegado: o passado do passado", r:"Quando dois fatos passados se encadeiam, o anterior vai no <b>pluscuamperfecto</b> (había + participio). <i>Cuando llegué, el tren ya <b>había salido</b></i>. Sem ele, a ordem fica ambígua.",
   ex:[["Cuando llegamos, ya habían cerrado.","Quando chegamos, já tinham fechado."],["Nunca había visto nada igual.","Nunca tinha visto nada igual."],["Habíamos reservado, pero no constaba.","Tínhamos reservado, mas não constava."]], bad:"'Cuando llegué el tren salió' diz que o trem saiu na hora, não antes."},
  {t:"Si hubiera sabido, habría venido", r:"Hipótese impossível (passado): <b>si + hubiera + participio</b>, resultado em <b>habría + participio</b>. Hipótese improvável (presente): <b>si + tuviera</b>, resultado em <b>tendría</b>. Nunca 'si tendría' nem 'si habría'.",
   ex:[["Si hubiera sabido, habría venido antes.","Se tivesse sabido, teria vindo antes."],["Si tuviera tiempo, iría a Cádiz.","Se tivesse tempo, iria a Cádiz."],["Si pudiera, me quedaría.","Se pudesse, ficaria."]], bad:"'Si tendría tiempo iría' é o erro clássico: depois de 'si' nunca vai condicional."},
  {t:"Tuviera, não 'tuviese'? Os dois valem", r:"O imperfecto de subjuntivo tem duas formas iguais: <b>-ra</b> (tuviera, fuera, hiciera) e <b>-se</b> (tuviese, fuese, hiciese). A <b>-ra</b> é a mais falada; a <b>-se</b> soa um pouco mais formal ou literária. Misturar na mesma frase é feio.",
   ex:[["Si fuera rico, viajaría más.","Se fosse rico, viajaria mais."],["Si fuese rico, viajaría más.","Se fosse rico, viajaria mais."],["Ojalá pudiéramos volver.","Quem dera pudéssemos voltar."]], bad:"'Si tuviera tiempo y pudiese' mistura as duas formas sem motivo."},
  {t:"Me alegra que hayas venido", r:"Emoção sobre algo que <b>já aconteceu</b> pede o <b>perfecto de subjuntivo</b>: haya + participio. Sobre algo em curso ou futuro, presente de subjuntivo: <i>me alegra que estés aquí</i>.",
   ex:[["Me alegra que hayas venido.","Fico feliz que você tenha vindo."],["Es una pena que no haya podido venir.","É uma pena que não tenha podido vir."],["Me alegra que estés mejor.","Fico feliz que você esteja melhor."]], bad:"'Me alegra que has venido' é o calco do português 'que você veio'."},
  {t:"Aunque sea × aunque es", r:"<b>Aunque + subjuntivo</b> = mesmo que (hipótese ou algo que não se afirma). <b>Aunque + indicativo</b> = embora (fato conhecido). <i>Aunque <b>llueva</b>, iremos</i> (não sei se vai chover) × <i>Aunque <b>llueve</b>, iremos</i> (está chovendo agora).",
   ex:[["Aunque sea caro, lo compro.","Mesmo que seja caro, compro."],["Aunque es caro, lo compro.","Embora seja caro, compro."],["Por muy tarde que sea, llámame.","Por mais tarde que seja, me liga."]], bad:"Usar sempre indicativo apaga a diferença entre 'embora' e 'mesmo que'."},
  {t:"Busco un hotel que tenga, conozco uno que tiene", r:"Oração relativa: se o antecedente é <b>desconhecido ou inexistente</b> (busco, necesito, no hay), <b>subjuntivo</b>. Se é <b>conhecido</b> (conozco, hay, tengo), <b>indicativo</b>.",
   ex:[["Busco un hotel que admita perros.","Procuro um hotel que aceite cachorros."],["Conozco un hotel que admite perros.","Conheço um hotel que aceita cachorros."],["No hay nadie que hable portugués.","Não há ninguém que fale português."]], bad:"'Busco un hotel que tiene piscina' sugere que você já sabe qual é."},
  {t:"De ahí que proponga: conectores com subjuntivo", r:"Alguns conectores formais exigem <b>subjuntivo</b>: <b>de ahí que</b>, <b>no es que</b>, <b>para que</b>, <b>a no ser que</b>, <b>con tal de que</b>, <b>antes de que</b>, <b>sin que</b>. Outros, indicativo: <b>puesto que, dado que, ya que, así que, por lo tanto</b>.",
   ex:[["De ahí que proponga otra fecha.","Daí eu propor outra data."],["No es que no quiera, sino que no puedo.","Não é que eu não queira, mas é que não posso."],["Puesto que no hay tiempo, lo dejamos.","Já que não há tempo, deixamos."]], bad:"'De ahí que propongo' soa a estrangeiro culto, mas errado."},
  {t:"Le agradecería que me confirmara", r:"A fórmula formal de pedido junta <b>condicional</b> no verbo principal e <b>imperfecto de subjuntivo</b> no pedido: <i>Le agradecería que me <b>enviara</b>…</i> Não 'que me envíe' (mistura de tempos) nem 'que me envía'.",
   ex:[["Le agradecería que me confirmara la hora.","Agradeceria que me confirmasse a hora."],["Les rogaría que no fumaran aquí.","Pediria que não fumassem aqui."],["Me gustaría que vinieras.","Gostaria que você viesse."]], bad:"'Le agradecería que me confirme' se ouve, mas o registro formal pede 'confirmara'."},
  {t:"Lo, le, la: o objeto certo", r:"<b>Lo/la</b> = objeto direto (a coisa ou pessoa): <i>lo vi, la compré</i>. <b>Le</b> = objeto indireto (a quem): <i>le di el libro</i>. Em Madri se ouve <b>leísmo</b> (<i>le vi</i> por lo vi) e até <b>laísmo</b> (<i>la dije</i>); não imite. <b>Se lo</b> = quando juntam le + lo: <i>se lo di</i>.",
   ex:[["Lo compré ayer.","Comprei ontem (o livro)."],["Le di las llaves a Carmen.","Dei as chaves para a Carmen."],["Se las di ayer.","Dei para ela ontem (as chaves)."]], bad:"'Le vi en el bar' é leísmo madrileno; o padrão é 'lo vi'."},
  {t:"Ser pan comido, não 'ser pão comido'", r:"Expressões idiomáticas não se traduzem palavra a palavra, nem do português para o espanhol. Falsos irmãos: 'pagar o pato' é <b>pagar el pato</b> (igual), mas 'ficar de cara' é <b>quedarse a cuadros</b>; 'encher linguiça' é <b>irse por las ramas</b>; 'quebrar o galho' é <b>echar un cable</b>.",
   ex:[["Es pan comido.","É moleza."],["Me quedé a cuadros.","Fiquei de cara."],["¿Me echas un cable?","Me quebra um galho?"],["No te vayas por las ramas.","Não enche linguiça."]], bad:"'Encher la lingüiza' não existe."},
  {t:"Pero × perro: o erre decide", r:"<b>Pero</b> (mas) tem erre simples, uma só vibração. <b>Perro</b> (cachorro) tem erre duplo. O mesmo com <b>caro/carro</b>, <b>coral/corral</b>, <b>cero/cerro</b>. Quem fala português tende a vibrar demais o <i>r</i> entre vogais.",
   ex:[["Pero no puedo.","Mas não posso."],["Tengo un perro.","Tenho um cachorro."],["Es caro.","É caro."],["Es un carro.","É uma carroça."]], bad:"'Perro no puedo' faz o espanhol sorrir, e você perceber."},
  {t:"Castellano em Barcelona", r:"<b>Español</b> e <b>castellano</b> são sinônimos, mas na Catalunha, no País Basco e na Galícia, onde há outra língua cooficial, dizer <b>castellano</b> mostra que você entende que o espanhol é uma das línguas do lugar, não a única. Pequeno gesto, grande efeito.",
   ex:[["Hablo castellano y un poco de catalán.","Falo castelhano e um pouco de catalão."],["¿Prefieres que hablemos en castellano?","Prefere que falemos em castelhano?"],["Aquí conviven dos lenguas.","Aqui convivem duas línguas."]], bad:"'¿Hablas español o catalán?' como se fossem excludentes."}
];
